import{_ as s,o as t,c as l,j as a,a as n}from"./chunks/framework.CAKCj7G0.js";const L=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Java/MyBatis/缓存.md","filePath":"Java/MyBatis/缓存.md","lastUpdated":1760888831000}'),i={name:"Java/MyBatis/缓存.md"};function o(r,e,S,c,d,p){return t(),l("div",null,[...e[0]||(e[0]=[a("h3",{id:"缓存机制",tabindex:"-1"},[n("缓存机制 "),a("a",{class:"header-anchor",href:"#缓存机制","aria-label":'Permalink to "缓存机制"'},"​")],-1),a("ul",null,[a("li",null,"一级缓存： 本地缓存，默认启用且不能关闭 存在于 SqlSession 的生命周期中。 在同一个 SqlSession 中将查询方法和结果存入一个 Map 中。 缓存失效：SqlSession 改变、查询条件改变、SqlSession 中间发生了增删改、手动清除缓存"),a("li",null,"二级缓存： 存在于 SqlSessionFactory 的生命周期中，与命名空间（Mapper.xml）绑定。实现了 SqlSession 间缓存数据共享，缓存粒度更细，能到 namespace。 所有 SELECT 语句都会被缓存，所有 INSERT、UPDATE、DELETE 语句均会刷新缓存，不会根据时间来刷新。 缓存会存储集合、对象（1024 个数据） 缓存是线程安全的（每个线程独有一份） 缓存使用 LRU 最近最少使用 算法来收回。 注：使用二级缓存进行多表查询时，极大可能出现脏数据。"),a("li",null,"使用$设置参数时,MyBatis会创建普通的SQL语句,然后在执行SQL 语句时将参数拼入SQL,而使用#设置参数时,MyBatis会创建预编译的SQL语句,然后在执行SQL时MyBatis会为预编译SQL中的占位符赋值。预编译的SQL语句执行效率高,并且可以防止注入攻击,效率和安全性都大大优于前者,但在解决一些特殊问题,如在一些根据不同的条件产生不同的动态列中,我们要传递SQL的列名,根据某些列进行排序,或者传递列名给SQL就只能使用$了")],-1)])])}const _=s(i,[["render",o]]);export{L as __pageData,_ as default};
